<?php
require_once __DIR__.'/bootstrap.lib.php';
require_once __DIR__.'/migrations.lib.php';
require_once __DIR__.'/cgnat.lib.php';
ipv6RequireMkAuthLogin();
$conn=new mysqli('127.0.0.1','root','vertrigo','mkradius');
ipv6RunMigrations($conn);
$downloadId=(int)($_GET['download_csv']??0);
if($downloadId>0){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="cgnat-'.$downloadId.'-conexoes.csv"');
 $out=fopen('php://output','w');fputs($out,"\xEF\xBB\xBF");fputcsv($out,array('Login','Inicio da conexao','Fim da conexao','Inicio da vigencia','Fim da vigencia','IP privado','IP publico','Porta inicial','Porta final'),';');
 $stmt=$conn->prepare("SELECT username,connection_start,connection_end,effective_start,effective_end,private_ip,public_ip,port_start,port_end FROM cgnat_connection_archive WHERE profile_id=? ORDER BY effective_start");$stmt->bind_param('i',$downloadId);$stmt->execute();$res=$stmt->get_result();while($r=$res->fetch_assoc())fputcsv($out,$r,';');$stmt->close();
 $stmt=$conn->prepare("SELECT r.username,r.acctstarttime,r.acctstoptime,IF(r.acctstarttime>v.started_at,r.acctstarttime,v.started_at),NOW(),r.framedipaddress,m.public_ip,m.port_start,m.port_end FROM cgnat_profile_periods v INNER JOIN radacct r ON r.acctstarttime<NOW() AND (r.acctstoptime IS NULL OR r.acctstoptime>v.started_at) LEFT JOIN cgnat_mappings m ON m.profile_id=v.profile_id AND m.private_ip=r.framedipaddress WHERE v.profile_id=? AND v.ended_at IS NULL AND v.superseded_at IS NULL ORDER BY r.acctstarttime");$stmt->bind_param('i',$downloadId);$stmt->execute();$res=$stmt->get_result();while($r=$res->fetch_row())fputcsv($out,$r,';');$stmt->close();fclose($out);exit;
}
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $id=(int)($_POST['profile_id']??0);
  if($id<1)throw new RuntimeException('Perfil CGNAT invalido.');
  if(isset($_POST['activate']) || isset($_POST['activate_retro'])){
   $effectiveDate=trim($_POST['effective_date']??'');
   cgnatActivateProfile($conn,$id,$effectiveDate);$message='CGNAT #'.$id.' ativado no cruzamento'.($effectiveDate!==''?' com vigencia retroativa desde '.date('d/m/Y H:i',strtotime($effectiveDate)):'').'. Clientes online e conexoes dentro desta vigencia passam a usar este mapeamento junto com os demais blocos ativos; os periodos substituidos continuam preservados para auditoria.';
  }elseif(isset($_POST['deactivate'])){
   cgnatDeactivateProfile($conn,$id);$message='CGNAT #'.$id.' desativado. O periodo foi encerrado e preservado no historico.';
  }elseif(isset($_POST['delete'])){
   $check=$conn->query('SELECT active FROM cgnat_profiles WHERE id='.$id)->fetch_assoc();
   if(!$check)throw new RuntimeException('Perfil nao encontrado.');
   if((int)$check['active']===1)throw new RuntimeException('Marque outro CGNAT como padrao antes de excluir o perfil atual.');
   if(!$conn->query('UPDATE cgnat_profiles SET deleted_at=NOW() WHERE id='.$id))throw new RuntimeException($conn->error);
   $message='CGNAT #'.$id.' arquivado. Mapeamentos e relatorios permanecerao guardados por dois anos.';
  }
 }catch(Exception $e){$conn->rollback();$error=$e->getMessage();}
}
$profiles=array();
$sql="SELECT p.*,COUNT(DISTINCT m.id) mapping_count,MIN(m.private_ip) first_private,MAX(m.private_ip) last_private,MIN(CASE WHEN v.superseded_at IS NULL THEN v.started_at END) first_started,MAX(CASE WHEN v.ended_at IS NULL AND v.superseded_at IS NULL THEN v.started_at END) current_started,MAX(CASE WHEN v.superseded_at IS NULL THEN v.ended_at END) last_ended FROM cgnat_profiles p LEFT JOIN cgnat_mappings m ON m.profile_id=p.id LEFT JOIN cgnat_profile_periods v ON v.profile_id=p.id GROUP BY p.id ORDER BY p.created_at DESC,p.id DESC";
$rows=$conn->query($sql);if($rows)while($row=$rows->fetch_assoc())$profiles[]=$row;
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
